solvers.source:
K = 100.0           #: K      strike
RATE = 0.05         #: RATE   risk-free interest rate, per year
SIGMA = 0.2         #: SIGMA  volatility, per root-year
T = 1.0             #: T      time to expiry, years
SMAX = 300.0        #: SMAX   where the grid stops: three strikes out
SMOOTHED = 2.0      #: SMOOTHED  how many opening steps `smooth` replaces by two half-steps each

#| The standard normal cumulative distribution.
def normal_cdf(x) {
    return 0.5 * (1.0 + erf(x / sqrt(2.0)))
}

#| The Black-Scholes closed form for a European call at stock price s.
def call_exact(s) {
    d1 = (log(s / K) + (RATE + 0.5 * SIGMA * SIGMA) * T) / (SIGMA * sqrt(T))
    d2 = d1 - SIGMA * sqrt(T)
    return s * normal_cdf(d1) - K * exp(-RATE * T) * normal_cdf(d2)
}

#| Its delta, dV/dS = N(d1).
def delta_exact(s) {
    d1 = (log(s / K) + (RATE + 0.5 * SIGMA * SIGMA) * T) / (SIGMA * sqrt(T))
    return normal_cdf(d1)
}

#| One theta-step of length dt from time-to-expiry tau: theta = 1 is implicit Euler,
#| theta = 1/2 Crank-Nicolson. `s` holds the n interior stock prices, spacing h.
def theta_step(v, s, h, tau, dt, theta) {
    n = len(v)
    diff = 0.5 * SIGMA * SIGMA * s * s / (h * h)
    drift = 0.5 * RATE * s / h
    low = diff - drift
    mid = -2.0 * diff - RATE
    high = diff + drift
    e = (1.0 - theta) * dt
    rhs = v + e * (low * roll(v, 1.0) + mid * v + high * roll(v, -1.0))
    # roll wraps around; the two edge rows see the boundary values instead
    edge_old = SMAX - K * exp(-RATE * tau)
    edge_new = SMAX - K * exp(-RATE * (tau + dt))
    last = n - 1.0
    rhs[0] = v[0] + e * (mid[0] * v[0] + high[0] * v[1])
    rhs[last] = v[last] + e * (low[last] * v[last - 1.0] + mid[last] * v[last] + high[last] * edge_old) + theta * dt * high[last] * edge_new
    return tridiag_solve(-theta * dt * low, 1.0 - theta * dt * mid, -theta * dt * high, rhs)
}

#| Price the call on n interior points in `steps` time steps. With `smooth`, the first two
#| steps are each replaced by two implicit-Euler half-steps.
def price_call(n, steps, smooth: Bool) {
    h = SMAX / (n + 1.0)
    s = linspace(h, SMAX - h, n)
    v = max(s - K, 0.0)
    dt = T / steps
    tau = 0.0
    first = 0.0
    if smooth {
        for q to 2.0 * SMOOTHED {
            v = theta_step(v, s, h, tau, 0.5 * dt, 1.0)
            tau = tau + 0.5 * dt
        }
        first = SMOOTHED
    }
    for m to steps - first {
        v = theta_step(v, s, h, tau, dt, 0.5)
        tau = tau + dt
    }
    return v
}

#| The worst error in the delta (a centered difference of the prices) within 20 of the strike.
def delta_error(n, steps, smooth: Bool) {
    h = SMAX / (n + 1.0)
    v = price_call(n, steps, smooth)
    worst = 0.0
    for i to n - 2.0 {
        s = (i + 2.0) * h
        if abs(s - K) < 20.0 {
            d = (v[i + 2.0] - v[i]) / (2.0 * h)
            worst = max(worst, abs(d - delta_exact(s)))
        }
    }
    return worst
}

#| The error in the at-the-money price. The strike sits on a grid point: (n + 1) / 3 is whole.
def price_error(n, steps, smooth: Bool) {
    v = price_call(n, steps, smooth)
    return abs(v[(n + 1.0) / 3.0 - 1.0] - call_exact(K))
}

N = 599
STEPS = 200
S = linspace(SMAX / (N + 1.0), SMAX - SMAX / (N + 1.0), N)
V = price_call(N, STEPS, true)
exact = call_exact(K)
computed = V[(N + 1.0) / 3.0 - 1.0]
show exact
show computed

# few, long time steps make dt / h^2 large: that is where the kink shows
rough = delta_error(599.0, 25.0, false)
smoothed = delta_error(599.0, 25.0, true)
show rough
show smoothed

order = log(price_error(149.0, 50.0, true) / price_error(299.0, 100.0, true)) / log(2.0)
show order

figure("A European call, one year from expiry", "stock price S", "value")
plot(S, max(S - K, 0.0), "payoff at expiry")
plot(S, V, "value today")

test "the at-the-money price matches the closed form to a tenth of a cent" {
    assert_near(computed, exact, 1.0e-3)
}
test "halving h and the time step together cuts the error by four: second order" {
    assert_near(order, 2.0, 0.1)
}
test "with long time steps, plain Crank-Nicolson leaves the kink ringing in the delta" {
    assert_gt(rough, 10.0 * smoothed)
}
test "four implicit half-steps at the start remove it" {
    assert_lt(smoothed, 1.0e-3)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

pi = 3.141592653589793
C = 1.0
NU = 0.5        #: NU  the Courant number c dt / dx

#| A smooth pulse on the ring.
def pulse(x) {
    return exp(-100.0 * (x - 0.5) * (x - 0.5))
}

#| Carry the pulse once around the ring with the upwind scheme; return what comes back.
def upwind_lap(n) {
    x = linspace(0.0, 1.0 - 1.0 / n, n)
    u = pulse(x)
    steps = n / (C * NU)
    for s to steps {
        u = u - NU * (u - roll(u, 1.0))
    }
    return u
}

#| The same trip with Lax-Wendroff.
def lax_wendroff_lap(n) {
    x = linspace(0.0, 1.0 - 1.0 / n, n)
    u = pulse(x)
    steps = n / (C * NU)
    for s to steps {
        right = roll(u, -1.0)
        left = roll(u, 1.0)
        u = u - 0.5 * NU * (right - left) + 0.5 * NU * NU * (right - 2.0 * u + left)
    }
    return u
}

#| L2 distance between what came back and what set out.
def lap_error(u, n) {
    x = linspace(0.0, 1.0 - 1.0 / n, n)
    d = u - pulse(x)
    return sqrt(sum(d * d) / n)
}

# upwind reaches its asymptotic order slowly, so it is measured on finer grids than it is drawn on
up1 = lap_error(upwind_lap(1600.0), 1600.0)
up2 = lap_error(upwind_lap(3200.0), 3200.0)
up_coarse = lap_error(upwind_lap(400.0), 400.0)
lw1 = lap_error(lax_wendroff_lap(200.0), 200.0)
lw2 = lap_error(lax_wendroff_lap(400.0), 400.0)
order_upwind = log(up1 / up2) / log(2.0)
order_lw = log(lw1 / lw2) / log(2.0)
show order_upwind
show order_lw
show up_coarse
show lw2

N = 200
X = linspace(0.0, 1.0 - 1.0 / N, N)
figure("One trip around the ring", "x", "u")
plot(X, pulse(X), "exact (the starting pulse)")
plot(X, upwind_lap(N), "upwind: it diffuses")
plot(X, lax_wendroff_lap(N), "Lax-Wendroff: it keeps its height")
style("exact (the starting pulse)", "dash")

test "upwind is first order (measured between n = 1600 and 3200: it gets there slowly)" {
    assert_near(order_upwind, 1.0, 0.05)
}
test "Lax-Wendroff is second order" {
    assert_near(order_lw, 2.0, 0.15)
}
test "at the same resolution Lax-Wendroff is more than ten times closer" {
    assert_lt(lw2 * 10.0, up_coarse)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

XMIN = -1.0
XMAX = 2.0

#| Godunov's flux at every face between a cell and its right neighbor.
def godunov_flux(u) {
    ul = max(u, 0.0)
    ur = min(roll(u, -1.0), 0.0)
    return max(0.5 * ul * ul, 0.5 * ur * ur)
}

#| March n cells to t_end from a step (left state, right state) at x = 0.
def march(n, t_end, left, right) {
    h = (XMAX - XMIN) / n
    u = zeros(n)
    for i to n {
        x = XMIN + (i + 0.5) * h
        u[i] = right
        if x < 0.0 { u[i] = left }
    }
    steps = round(t_end / (0.5 * h))
    dt = t_end / steps
    hold = zeros(n) + 1.0
    hold[0] = 0.0
    hold[n - 1.0] = 0.0
    for s to steps {
        f = godunov_flux(u)
        u = u - (dt / h) * (f - roll(f, 1.0)) * hold
    }
    return u
}

N = 300
H = (XMAX - XMIN) / N
T_END = 1.2
shock = march(N, T_END, 1.0, 0.0)
fan = march(N, T_END, 0.0, 1.0)

# the shock: where is it, and was anything lost?
mass = sum(shock) * H
mass_exact = (0.0 - XMIN) + 0.5 * T_END
position = XMIN + mass
show mass
show position

# the fan: compare with u = x/t inside it
fan_error = 0.0
X = zeros(N)
FAN_EXACT = zeros(N)
for i to N {
    X[i] = XMIN + (i + 0.5) * H
    e = 0.0
    if X[i] > 0.0 { e = min(X[i] / T_END, 1.0) }
    FAN_EXACT[i] = e
    fan_error = fan_error + abs(fan[i] - e) * H
}
show fan_error

figure("Two Riemann problems for Burgers' equation at t = 1.2", "x", "u")
plot(X, shock, "$u_L = 1$, $u_R = 0$: a shock at $x = t/2$")
plot(X, fan, "$u_L = 0$, $u_R = 1$: a rarefaction, computed")
plot(X, FAN_EXACT, "the fan u = x/t, exact")

test "conservation is exact: the mass is what flowed in, to rounding" {
    assert_near(mass, mass_exact, 1.0e-12)
}
test "so the shock sits at x = t/2, the Rankine-Hugoniot speed" {
    assert_near(position, 0.5 * T_END, 1.0e-12)
}
test "the shock is captured in at most three cells, with no overshoot" {
    worst = 0.0
    smeared = 0.0
    for i to N {
        worst = max(worst, shock[i] - 1.0)
        worst = max(worst, 0.0 - shock[i])
        if shock[i] > 0.01 and shock[i] < 0.99 { smeared = smeared + 1.0 }
    }
    assert_lt(worst, 1.0e-12)
    assert_lt(smeared, 3.5)
}
test "the rarefaction opens into the fan u = x/t, not an expansion shock" {
    assert_lt(fan_error, 0.02)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

G = 1.4                 #: G  ratio of specific heats, gamma
RHO_L = 1.0
P_L = 1.0
RHO_R = 0.125
P_R = 0.1
T_END = 0.2
X_MEMBRANE = 0.5
NVAR = 3.0              #: NVAR  conserved variables per cell: rho, rho u, E
STAR_BISECTIONS = 80.0  #: STAR_BISECTIONS  halvings of the bracket around the star pressure

#| One side's term in the pressure equation: a shock if p is above that side's pressure, a rarefaction if below.
def pressure_term(p, rho_k, p_k) {
    a_k = sqrt(G * p_k / rho_k)
    if p > p_k {
        return (p - p_k) * sqrt((2.0 / ((G + 1.0) * rho_k)) / (p + (G - 1.0) / (G + 1.0) * p_k))
    }
    return 2.0 * a_k / (G - 1.0) * (pow(p / p_k, (G - 1.0) / (2.0 * G)) - 1.0)
}

#| The pressure between the waves, by bisection. Both gases start at rest.
def star_pressure() {
    lo = 1.0e-9
    hi = P_L
    for it to STAR_BISECTIONS {
        mid = 0.5 * (lo + hi)
        if pressure_term(mid, RHO_L, P_L) + pressure_term(mid, RHO_R, P_R) > 0.0 {
            hi = mid
        }
        else {
            lo = mid
        }
    }
    return 0.5 * (lo + hi)
}

P_STAR = star_pressure()
U_STAR = 0.5 * (pressure_term(P_STAR, RHO_R, P_R) - pressure_term(P_STAR, RHO_L, P_L))
A_L = sqrt(G * P_L / RHO_L)
A_R = sqrt(G * P_R / RHO_R)
RHO_STAR_L = RHO_L * pow(P_STAR / P_L, 1.0 / G)                  # isentropic, through the fan
GM = (G - 1.0) / (G + 1.0)
RHO_STAR_R = RHO_R * (P_STAR / P_R + GM) / (GM * P_STAR / P_R + 1.0)      # across the shock
SHOCK_SPEED = A_R * sqrt((G + 1.0) / (2.0 * G) * P_STAR / P_R + (G - 1.0) / (2.0 * G))
TAIL_SPEED = U_STAR - A_L * pow(P_STAR / P_L, (G - 1.0) / (2.0 * G))
show P_STAR
show U_STAR
show RHO_STAR_L
show RHO_STAR_R
show SHOCK_SPEED

#| The exact density at the points x, at time t: left state, fan, two plateaus, right state.
def exact_density(x, t) {
    n = len(x)
    rho = zeros(n)
    for i to n {
        xi = (x[i] - X_MEMBRANE) / t
        if xi < -A_L {
            rho[i] = RHO_L
        }
        else if xi < TAIL_SPEED {
            rho[i] = RHO_L * pow(2.0 / (G + 1.0) - GM * xi / A_L, 2.0 / (G - 1.0))
        }
        else if xi < U_STAR {
            rho[i] = RHO_STAR_L
        }
        else if xi < SHOCK_SPEED {
            rho[i] = RHO_STAR_R
        }
        else {
            rho[i] = RHO_R
        }
    }
    return rho
}

#| Pressure from the conserved variables, a 3 x m array of (rho, rho u, E).
def pressure(q) {
    mom = slab(q, 1.0)
    return (G - 1.0) * (slab(q, 2.0) - 0.5 * mom * mom / slab(q, 0.0))
}

#| The physical flux of each cell's state.
def physical_flux(q) {
    rho = slab(q, 0.0)
    mom = slab(q, 1.0)
    p = pressure(q)
    u = mom / rho
    f = zeros(NVAR, len(rho))
    setslab(f, 0.0, mom)
    setslab(f, 1.0, mom * u + p)
    setslab(f, 2.0, (slab(q, 2.0) + p) * u)
    return f
}

#| The HLL flux through every cell's RIGHT wall (column i: between cells i and i + 1).
def hll_flux(q) {
    rho = slab(q, 0.0)
    u = slab(q, 1.0) / rho
    a = sqrt(G * pressure(q) / rho)
    s_left = min(min(u - a, roll(u - a, -1.0)), 0.0)
    s_right = max(max(u + a, roll(u + a, -1.0)), 0.0)
    f = physical_flux(q)
    f_next = roll(f, -1.0, 1.0)
    q_next = roll(q, -1.0, 1.0)
    out = zeros(NVAR, len(rho))
    for k to NVAR {
        fl = slab(f, k)
        fr = slab(f_next, k)
        dq = slab(q_next, k) - slab(q, k)
        setslab(out, k, (s_right * fl - s_left * fr + s_left * s_right * dq) / (s_right - s_left))
    }
    return out
}

#| Sod's initial state on n cells plus one ghost cell at each end.
def initial_state(n) {
    dx = 1.0 / n
    q = zeros(NVAR, n + 2.0)
    for i to n + 2.0 {
        x = (i - 0.5) * dx
        if x < X_MEMBRANE {
            q[0, i] = RHO_L
            q[2, i] = P_L / (G - 1.0)
        }
        else {
            q[0, i] = RHO_R
            q[2, i] = P_R / (G - 1.0)
        }
    }
    return q
}

#| March n cells to T_END at a Courant number of 0.9. The ghost cells copy their neighbors.
def solve_sod(n) {
    dx = 1.0 / n
    q = initial_state(n)
    t = 0.0
    while t < T_END {
        rho = slab(q, 0.0)
        speed = max(abs(slab(q, 1.0) / rho) + sqrt(G * pressure(q) / rho))
        dt = min(0.9 * dx / speed, T_END - t)
        f = hll_flux(q)
        q = q - (dt / dx) * (f - roll(f, 1.0, 1.0))
        for k to NVAR {
            q[k, 0] = q[k, 1]
            q[k, n + 1.0] = q[k, n]
        }
        t = t + dt
    }
    return q
}

#| Cell centers, ghosts included.
def centers(n) {
    dx = 1.0 / n
    return linspace(-0.5 * dx, 1.0 + 0.5 * dx, n + 2.0)
}

#| L1 error of the density over the interior cells.
def density_error(n) {
    d = abs(slab(solve_sod(n), 0.0) - exact_density(centers(n), T_END))
    return (sum(d) - d[0] - d[n + 1.0]) / n
}

N = 400
X = centers(N)
Q = solve_sod(N)
RHO = slab(Q, 0.0)
VEL = slab(Q, 1.0) / RHO
PRS = pressure(Q)

# conservation: nothing has reached the walls, so interior mass and energy cannot have changed
mass = (sum(RHO) - RHO[0] - RHO[N + 1.0]) / N
energy = (sum(slab(Q, 2.0)) - Q[2, 0] - Q[2, N + 1.0]) / N
mass_0 = 0.5 * (RHO_L + RHO_R)
energy_0 = 0.5 * (P_L + P_R) / (G - 1.0)
momentum = (sum(slab(Q, 1.0)) - Q[1, 0] - Q[1, N + 1.0]) / N
show mass
show energy
show momentum

# the plateau between contact and shock, sampled at its middle
x_contact = X_MEMBRANE + U_STAR * T_END
x_shock = X_MEMBRANE + SHOCK_SPEED * T_END
i_mid = round(0.5 * (x_contact + x_shock) * N + 0.5)
plateau_u = VEL[i_mid]
plateau_p = PRS[i_mid]
show plateau_u
show plateau_p

# the computed shock: where the density crosses halfway between the two states it separates
found_shock = 0.0
for i to N {
    half = 0.5 * (RHO_STAR_R + RHO_R)
    if RHO[i] >= half and RHO[i + 1.0] < half {
        found_shock = X[i] + (X[i + 1.0] - X[i]) * (RHO[i] - half) / (RHO[i] - RHO[i + 1.0])
    }
}
show x_shock
show found_shock

err_200 = density_error(200.0)
err_400 = density_error(400.0)
l1_order = log(err_200 / err_400) / log(2.0)
show err_200
show err_400
show l1_order

figure("Sod's shock tube at t = 0.2: fan, contact, shock", "x", "density")
plot(X, exact_density(X, T_END), "exact")
plot(X, RHO, "HLL, 400 cells")
style("exact", "dash")

test "the exact shock obeys the jump conditions: mass and momentum through it balance" {
    mass_in = RHO_R * (0.0 - SHOCK_SPEED)
    mass_out = RHO_STAR_R * (U_STAR - SHOCK_SPEED)
    assert_near(mass_in, mass_out, 1.0e-12)
    assert_near(mass_out * U_STAR + P_STAR, P_R, 1.0e-12)
}
test "and energy: (E + p)(u - S) + p S balances across it" {
    e_star = P_STAR / (G - 1.0) + 0.5 * RHO_STAR_R * U_STAR * U_STAR
    e_right = P_R / (G - 1.0)
    assert_near(e_star * (U_STAR - SHOCK_SPEED) + P_STAR * U_STAR, e_right * (0.0 - SHOCK_SPEED), 1.0e-12)
}
test "mass and energy are conserved to rounding" {
    assert_near(mass, mass_0, 1.0e-13)
    assert_near(energy, energy_0, 1.0e-13)
}
test "momentum grows by exactly the pressure difference times the time" {
    assert_near(momentum, (P_L - P_R) * T_END, 1.0e-13)
}
test "between contact and shock the computed velocity and pressure sit on the exact plateau" {
    assert_near(plateau_u, U_STAR, 0.005)
    assert_near(plateau_p, P_STAR, 0.002)
}
test "the shock is where the exact solution puts it, to within a cell" {
    assert_near(found_shock, x_shock, 1.0 / N)
}
test "the density converges in L1, at an order below one: the contact smears like sqrt(t)" {
    assert_gt(l1_order, 0.5)
    assert_lt(l1_order, 1.0)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

pi = 3.141592653589793

#| Apply -h^2 Laplacian to a padded (n+2) x (n+2) grid; the boundary ring stays zero.
def apply_laplacian(u, mask) {
    lap = 4.0 * u - roll(u, 1.0, 0.0) - roll(u, -1.0, 0.0) - roll(u, 1.0, 1.0) - roll(u, -1.0, 1.0)
    return lap * mask
}

#| 1 on interior points, 0 on the boundary ring.
def interior_mask(n) {
    m = zeros(n + 2.0, n + 2.0)
    for i to n {
        for j to n {
            m[i + 1.0, j + 1.0] = 1.0
        }
    }
    return m
}

#| The manufactured solution sampled on the padded grid.
def exact_solution(n) {
    h = 1.0 / (n + 1.0)
    x = reshape(arange(n + 2.0) * h, -1, 1)   # a column: x runs down the rows
    y = arange(n + 2.0) * h                   # a row: y runs across
    return sin(pi * x) * sin(2.0 * pi * y) + x * (1.0 - x) * y * (1.0 - y)
}

#| Its right-hand side, f = -Laplacian(u), worked out by hand.
def right_hand_side(n) {
    h = 1.0 / (n + 1.0)
    x = reshape(arange(n + 2.0) * h, -1, 1)
    y = arange(n + 2.0) * h
    return 5.0 * pi * pi * sin(pi * x) * sin(2.0 * pi * y) + 2.0 * x * (1.0 - x) + 2.0 * y * (1.0 - y)
}

ITERS = zeros(1)        #: ITERS  how many CG steps the last solve took (a one-element out-parameter)

#| Solve -Laplacian u = f on an n x n interior by conjugate gradients.
def solve_poisson(n) {
    h = 1.0 / (n + 1.0)
    mask = interior_mask(n)
    b = (h * h) * right_hand_side(n) * mask
    u = zeros(n + 2.0, n + 2.0)
    r = b
    p = r
    rr = sum(r * r)
    target = 1.0e-20 * rr
    k = 0.0
    while rr > target and k < 2000.0 {
        ap = apply_laplacian(p, mask)
        alpha = rr / sum(p * ap)
        u = u + alpha * p
        r = r - alpha * ap
        rr_new = sum(r * r)
        p = r + (rr_new / rr) * p
        rr = rr_new
        k = k + 1.0
    }
    ITERS[0] = k
    return u
}

#| L2 error of the solve on an n x n grid.
def poisson_error(n) {
    h = 1.0 / (n + 1.0)
    d = solve_poisson(n) - exact_solution(n)
    return sqrt(sum(d * d)) * h
}

e1 = poisson_error(16.0)
e2 = poisson_error(33.0)
iters = ITERS[0]
order = log(e1 / e2) / log(2.0)
show e1
show e2
show order
show iters

# u[i, j] is the solution at x = i h, y = j h: transposed, x runs across and y up
figure("The solution of Poisson's equation", "x", "y")
origin("lower")
plot2d(transpose(solve_poisson(40.0)), "u")

test "the solve matches the manufactured solution" {
    assert_lt(e2, 2.0e-3)
}
test "the five-point Laplacian is second order" {
    assert_near(order, 2.0, 0.1)
}
test "conjugate gradients needs far fewer steps than there are unknowns (33 x 33 = 1089)" {
    assert_lt(iters, 120.0)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

pi = 3.141592653589793

#| The n^2 x n^2 five-point Laplacian on an n x n interior, Dirichlet, scaled by 1/h^2.
def laplacian_matrix(n) {
    h = 1.0 / (n + 1.0)
    s = 1.0 / (h * h)
    A = zeros(n * n, n * n)
    for i to n {
        for j to n {
            row = i * n + j
            A[row, row] = 4.0 * s
            if i > 0.0 { A[row, row - n] = -s }
            if i < n - 1.0 { A[row, row + n] = -s }
            if j > 0.0 { A[row, row - 1.0] = -s }
            if j < n - 1.0 { A[row, row + 1.0] = -s }
        }
    }
    return A
}

#| The closed-form discrete eigenvalue for mode (m, n).
def discrete_lambda(m, n, h) {
    a = sin(0.5 * m * pi * h)
    b = sin(0.5 * n * pi * h)
    return 4.0 / (h * h) * (a * a + b * b)
}

#| The relative error of the lowest eigenvalue against 2 pi^2, on an n x n grid.
def fundamental_error(n) {
    vals = zeros(n * n)
    vecs = zeros(n * n, n * n)
    eig_sym(laplacian_matrix(n), vals, vecs)
    return abs(vals[0] - 2.0 * pi * pi) / (2.0 * pi * pi)
}

N = 12
H = 1.0 / (N + 1.0)
VALS = zeros(N * N)
VECS = zeros(N * N, N * N)
eig_sym(laplacian_matrix(N), VALS, VECS)
lowest = VALS[0] / (pi * pi)
second = VALS[1] / (pi * pi)
third = VALS[2] / (pi * pi)
fourth = VALS[3] / (pi * pi)
show lowest
show second
show third
show fourth
order = log(fundamental_error(6.0) / fundamental_error(13.0)) / log(2.0)
show order

# the (2, 2) mode, the fourth eigenvector, reshaped onto the grid
MODE = zeros(N, N)
for i to N {
    for j to N {
        MODE[i, j] = VECS[i * N + j, 3.0]
    }
}
# MODE[i, j] is the displacement at x = (i + 1) h, y = (j + 1) h: transposed, x runs
# across and y up; the mode is signed, so the colors are centered on zero
figure("The (2, 2) mode of a square drum", "x", "y")
origin("lower")
colormap("diverging")
plot2d(transpose(MODE), "u")

test "the eigensolver reproduces the discrete eigenvalues in closed form, to rounding" {
    assert_near(VALS[0], discrete_lambda(1.0, 1.0, H), 1.0e-9)
    assert_near(VALS[1], discrete_lambda(1.0, 2.0, H), 1.0e-9)
    assert_near(VALS[3], discrete_lambda(2.0, 2.0, H), 1.0e-9)
    assert_near(VALS[N * N - 1.0], discrete_lambda(N, N, H), 1.0e-8)
}
test "a square drum's (1,2) and (2,1) modes are degenerate" {
    assert_near(VALS[1], VALS[2], 1.0e-9)
}
test "the continuum values pi^2 (m^2 + n^2) are approached at second order" {
    assert_near(lowest, 2.0, 0.02)
    assert_near(fourth, 8.0, 0.35)
    assert_near(order, 2.0, 0.1)
}

