<span class="tk-fn">eig_sym</span>(<span class="tk-call">laplacian_matrix</span>(N), VALS, VECS)
lowest <span class="tk-op">=</span> VALS[<span class="tk-num">0</span>] <span class="tk-op">/</span> (pi <span class="tk-op">*</span> pi)
second <span class="tk-op">=</span> VALS[<span class="tk-num">1</span>] <span class="tk-op">/</span> (pi <span class="tk-op">*</span> pi)
third <span class="tk-op">=</span> VALS[<span class="tk-num">2</span>] <span class="tk-op">/</span> (pi <span class="tk-op">*</span> pi)
fourth <span class="tk-op">=</span> VALS[<span class="tk-num">3</span>] <span class="tk-op">/</span> (pi <span class="tk-op">*</span> pi)
<span class="tk-kw">show</span> lowest
<span class="tk-kw">show</span> second
<span class="tk-kw">show</span> third
<span class="tk-kw">show</span> fourth
order <span class="tk-op">=</span> <span class="tk-fn">log</span>(<span class="tk-call">fundamental_error</span>(<span class="tk-num">6.0</span>) <span class="tk-op">/</span> <span class="tk-call">fundamental_error</span>(<span class="tk-num">13.0</span>)) <span class="tk-op">/</span> <span class="tk-fn">log</span>(<span class="tk-num">2.0</span>)
<span class="tk-kw">show</span> order

<span class="tk-com"># the (2, 2) mode, the fourth eigenvector, reshaped onto the grid</span>
MODE <span class="tk-op">=</span> <span class="tk-fn">zeros</span>(N, N)
<span class="tk-kw">for</span> i <span class="tk-kw">to</span> N {
    <span class="tk-kw">for</span> j <span class="tk-kw">to</span> N {
        MODE[i, j] <span class="tk-op">=</span> VECS[i <span class="tk-op">*</span> N <span class="tk-op">+</span> j, <span class="tk-num">3.0</span>]
    }
}
<span class="tk-com"># MODE[i, j] is the displacement at x = (i + 1) h, y = (j + 1) h: transposed, x runs</span>
<span class="tk-com"># across and y up; the mode is signed, so the colors are centered on zero</span>
<span class="tk-fn">figure</span>(<span class="tk-str">"The (2, 2) mode of a square drum"</span>, <span class="tk-str">"x"</span>, <span class="tk-str">"y"</span>)
<span class="tk-fn">origin</span>(<span class="tk-str">"lower"</span>)
<span class="tk-call">colormap</span>(<span class="tk-str">"diverging"</span>)
<span class="tk-fn">plot2d</span>(<span class="tk-fn">transpose</span>(MODE), <span class="tk-str">"u"</span>)

<span class="tk-kw">test</span> <span class="tk-str">"the eigensolver reproduces the discrete eigenvalues in closed form, to rounding"</span> {
    <span class="tk-fn">assert_near</span>(VALS[<span class="tk-num">0</span>], <span class="tk-call">discrete_lambda</span>(<span class="tk-num">1.0</span>, <span class="tk-num">1.0</span>, H), <span class="tk-num">1.0e-9</span>)
    <span class="tk-fn">assert_near</span>(VALS[<span class="tk-num">1</span>], <span class="tk-call">discrete_lambda</span>(<span class="tk-num">1.0</span>, <span class="tk-num">2.0</span>, H), <span class="tk-num">1.0e-9</span>)
    <span class="tk-fn">assert_near</span>(VALS[<span class="tk-num">3</span>], <span class="tk-call">discrete_lambda</span>(<span class="tk-num">2.0</span>, <span class="tk-num">2.0</span>, H), <span class="tk-num">1.0e-9</span>)
    <span class="tk-fn">assert_near</span>(VALS[N <span class="tk-op">*</span> N <span class="tk-op">-</span> <span class="tk-num">1.0</span>], <span class="tk-call">discrete_lambda</span>(N, N, H), <span class="tk-num">1.0e-8</span>)
}
<span class="tk-kw">test</span> <span class="tk-str">"a square drum's (1,2) and (2,1) modes are degenerate"</span> {
    <span class="tk-fn">assert_near</span>(VALS[<span class="tk-num">1</span>], VALS[<span class="tk-num">2</span>], <span class="tk-num">1.0e-9</span>)
}
<span class="tk-kw">test</span> <span class="tk-str">"the continuum values pi^2 (m^2 + n^2) are approached at second order"</span> {
    <span class="tk-fn">assert_near</span>(lowest, <span class="tk-num">2.0</span>, <span class="tk-num">0.02</span>)
    <span class="tk-fn">assert_near</span>(fourth, <span class="tk-num">8.0</span>, <span class="tk-num">0.35</span>)
    <span class="tk-fn">assert_near</span>(order, <span class="tk-num">2.0</span>, <span class="tk-num">0.1</span>)
}

