solvers.source:
pi = 3.141592653589793
N = 256
L = 40.0
DX = L / N
X = linspace(-0.5 * L, 0.5 * L - DX, N)
K = zeros(N)
for j to N {
    K[j] = 2.0 * pi * j / L
    if j >= N / 2.0 { K[j] = 2.0 * pi * (j - N) / L }
}
SECH = 1.0 / cosh(X)

#| exp(+i theta) for a real array theta.
def phase(theta) {
    return complex(cos(theta), sin(theta))
}

#| Evolve the soliton to time t_end in `steps` Strang steps.
def evolve(t_end, steps) {
    dt = t_end / steps
    dispersion = phase(-0.5 * K * K * dt)
    psi = complex(SECH, zeros(N))
    for s to steps {
        psi = psi * phase(0.5 * dt * abs(psi) * abs(psi))
        fft(psi)
        psi = psi * dispersion
        ifft(psi)
        psi = psi * phase(0.5 * dt * abs(psi) * abs(psi))
    }
    return psi
}

#| The phase of psi at x = 0, in radians.
def center_phase(psi) {
    z = psi[N / 2.0]
    return atan2(im(z), re(z))
}

T_END = 2.0
psi = evolve(T_END, 400.0)
shape = abs(psi) - SECH
shape_error = sqrt(sum(shape * shape) * DX)
norm = sum(abs(psi) * abs(psi)) * DX
phase_now = center_phase(psi)
p1 = abs(center_phase(evolve(T_END, 100.0)) - 0.5 * T_END)
p2 = abs(center_phase(evolve(T_END, 200.0)) - 0.5 * T_END)
order = log(p1 / p2) / log(2.0)
show shape_error
show norm
show phase_now
show order

figure("A bright soliton: the modulus does not move", "x", "$|\\psi|$")
plot(X, SECH, "t = 0")
plot(X, abs(psi), "t = 2")

test "the soliton keeps its shape: |psi| is still sech(x)" {
    assert_lt(shape_error, 1.0e-5)
}
test "its phase turns at rate 1/2: arg psi(0, t) = t/2" {
    assert_near(phase_now, 0.5 * T_END, 1.0e-4)
}
test "the norm, 2 for sech(x), is conserved to rounding" {
    assert_near(norm, 2.0, 1.0e-10)
}
test "the splitting is second order" {
    assert_near(order, 2.0, 0.1)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

XMAX = 140.0
N = 700
H = XMAX / (N + 1.0)
X = linspace(H, XMAX - H, N)
DT = 0.05
R = DT / (H * H)

#| The logistic equation u' = u (1 - u), solved exactly over a time dt.
def react(u, dt) {
    g = exp(dt)
    return u * g / (1.0 + u * (g - 1.0))
}

LO = zeros(N) - 0.5 * R
DI = zeros(N) + (1.0 + R)
UP = zeros(N) - 0.5 * R

#| One Crank-Nicolson diffusion step, with u = 1 held at the left wall and 0 at the right.
def diffuse(u) {
    rhs = (1.0 - R) * u + 0.5 * R * (roll(u, 1.0) + roll(u, -1.0))
    # roll wraps around: put the true boundary neighbors back, for both time levels
    rhs[0] = (1.0 - R) * u[0] + 0.5 * R * (1.0 + u[1]) + 0.5 * R
    rhs[N - 1.0] = (1.0 - R) * u[N - 1.0] + 0.5 * R * u[N - 2.0]
    return tridiag_solve(LO, DI, UP, rhs)
}

#| Where the front is: the u = 1/2 crossing, by linear interpolation.
def front(u) {
    pos = 0.0
    for i to N - 1.0 {
        if u[i] >= 0.5 and u[i + 1.0] < 0.5 {
            pos = X[i] + H * (u[i] - 0.5) / (u[i] - u[i + 1.0])
        }
    }
    return pos
}

u = zeros(N)
for i to N {
    if X[i] < 5.0 { u[i] = 1.0 }
}
T1 = 20.0
T2 = 40.0
x1 = 0.0
snapshot = u
steps = T2 / DT
for s to steps {
    u = react(diffuse(react(u, 0.5 * DT)), 0.5 * DT)
    if s + 1.0 == T1 / DT {
        x1 = front(u)
        snapshot = u
    }
}
x2 = front(u)
speed = (x2 - x1) / (T2 - T1)
bramson = 2.0 - 1.5 * log(T2 / T1) / (T2 - T1)
show x1
show x2
show speed
show bramson

figure("A Fisher-KPP front, twenty time units apart", "x", "u")
plot(X, snapshot, "t = 20")
plot(X, u, "t = 40")

test "the front advances at the KPP speed 2, to within four percent" {
    assert_near(speed, 2.0, 0.08)
}
test "and from BELOW: the selected front is the slowest one, approached slowly" {
    assert_lt(speed, 2.0)
}
test "the shortfall is Bramson's logarithmic correction: 2 - (3/2) ln(t2/t1) / (t2 - t1)" {
    assert_near(speed, bramson, 0.01)
}

